package sandbox

import (
	"fmt"
	"os"
	"path/filepath"
)

// SynthesizeNixOSMicroVMModule synthesizes a declarative, hardened NixOS Firecracker MicroVM module.
func SynthesizeNixOSMicroVMModule(vmID string) string {
	if vmID == "" {
		vmID = "sandbox-runner-01"
	}
	return fmt.Sprintf(`# Declarative Hardened NixOS Ephemeral MicroVM Sandbox
# Generated by nix-k8s-sentinel (Version: 0.19.0)
{ config, pkgs, lib, ... }:

{
  microvm.vms.%s = {
    hypervisor = "firecracker";
    vcpu = 2;
    mem = 2048;
    kvmDevice = "/dev/kvm";
    kernelPath = "${pkgs.linuxPackages_latest.kernel}/vmlinux";
    rootfsPath = "/var/lib/microvms/%s/rootfs.ext4";
    readOnly = true;
    isolateEgress = true;

    jailer = {
      enable = true;
      user = "firecracker";
      group = "firecracker";
      chrootPath = "/srv/jailer/firecracker/%s";
      cgroups = {
        cpu_weight = 50;
        memory_max = "2147483648"; # 2GiB hard ceiling
      };
    };

    interfaces = [
      {
        type = "tap";
        id = "vm-detonate0";
        mac = "02:fc:00:00:00:01";
        isolateEgress = true;
      }
    ];

    shares = [
      {
        tag = "nix-store-ro";
        source = "/nix/store";
        mountPoint = "/nix/store";
        readOnly = true;
      }
    ];
  };
}
`, vmID, vmID, vmID)
}

// SynthesizeK8sDetonationJob synthesizes a declarative Kubernetes DetonationJob manifest.
func SynthesizeK8sDetonationJob(jobName, payloadDigest string) string {
	if jobName == "" {
		jobName = "detonation-job-01"
	}
	if payloadDigest == "" {
		payloadDigest = "sha256:e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855"
	}

	return fmt.Sprintf(`apiVersion: sentinel.io/v1alpha1
kind: DetonationJob
metadata:
  name: %s
  namespace: sentinel-sandbox
  labels:
    app.kubernetes.io/managed-by: nix-k8s-sentinel
    security.sentinel.io/sandbox: firecracker
spec:
  hypervisor: firecracker
  vcpus: 2
  memoryMib: 2048
  jailerEnabled: true
  egressIsolated: true
  readOnlyRootfs: true
  timeoutSeconds: 30
  payload:
    targetType: container_image
    payloadDigest: "%s"
    quarantineOnAnomaly: true
  honeypotLures:
    kubeletDecoy: true
    etcdDecoy: true
    canaryToken: true
`, jobName, payloadDigest)
}

// SynthesizeHoneypotLures synthesizes declarative decoy honeypot service definitions.
func SynthesizeHoneypotLures() string {
	return `apiVersion: v1
kind: ConfigMap
metadata:
  name: sentinel-honeypot-lures
  namespace: sentinel-sandbox
data:
  honeypot.yaml: |
    lures:
      - name: kubelet-api-decoy
        port: 10250
        protocol: HTTP
        responseType: UNATHORIZED_CHALLENGE
        alertSeverity: HIGH
      - name: etcd-peer-decoy
        port: 2379
        protocol: GRPC
        responseType: CONNECTION_STALL
        alertSeverity: CRITICAL
      - name: canary-serviceaccount-token
        path: /var/run/secrets/kubernetes.io/serviceaccount/token
        canaryHash: 7f83b1657ff1fc53b92dc18148a1d65dfc2d4b1fa3d677284addd200126d9069
        alertSeverity: HIGH
`
}

// WriteSynthesizedSandboxConfigs writes synthesized configs to the target directory.
func WriteSynthesizedSandboxConfigs(outDir string) (map[string]string, error) {
	if err := os.MkdirAll(outDir, 0755); err != nil {
		return nil, fmt.Errorf("failed to create output directory %s: %w", outDir, err)
	}

	results := make(map[string]string)

	nixPath := filepath.Join(outDir, "microvm-sandbox.nix")
	if err := os.WriteFile(nixPath, []byte(SynthesizeNixOSMicroVMModule("sandbox-runner-01")), 0644); err != nil {
		return nil, fmt.Errorf("failed to write %s: %w", nixPath, err)
	}
	results["nixos_microvm"] = nixPath

	k8sPath := filepath.Join(outDir, "detonation-job.yaml")
	if err := os.WriteFile(k8sPath, []byte(SynthesizeK8sDetonationJob("detonation-job-01", "sha256:d41d8cd98f00b204e9800998ecf8427e")), 0644); err != nil {
		return nil, fmt.Errorf("failed to write %s: %w", k8sPath, err)
	}
	results["k8s_detonation_job"] = k8sPath

	lurePath := filepath.Join(outDir, "honeypot-lures.yaml")
	if err := os.WriteFile(lurePath, []byte(SynthesizeHoneypotLures()), 0644); err != nil {
		return nil, fmt.Errorf("failed to write %s: %w", lurePath, err)
	}
	results["honeypot_lures"] = lurePath

	return results, nil
}
